const { useEffect, useLayoutEffect, useRef, useState } = React;

// ---- Anchor Positioning 实验台（本文各块共用）----

// 拖动锚点：位置存为舞台宽高的比例，舞台缩放时锚点跟着走
const useDraggable = (stageRef, initial) => {
  const [point, setPoint] = useState(initial);
  const onPointerDown = event => {
    const stage = stageRef.current;
    const handle = event.currentTarget;
    handle.setPointerCapture(event.pointerId);
    const rect = stage.getBoundingClientRect();
    const half = handle.getBoundingClientRect();
    const offsetX = event.clientX - (half.left + half.width / 2);
    const offsetY = event.clientY - (half.top + half.height / 2);
    const move = moveEvent => {
      const minX = half.width / 2 / rect.width;
      const minY = half.height / 2 / rect.height;
      const x = (moveEvent.clientX - offsetX - rect.left) / rect.width;
      const y = (moveEvent.clientY - offsetY - rect.top) / rect.height;
      setPoint({ x: Math.min(1 - minX, Math.max(minX, x)), y: Math.min(1 - minY, Math.max(minY, y)) });
    };
    const up = () => {
      handle.removeEventListener("pointermove", move);
      handle.removeEventListener("pointerup", up);
      handle.removeEventListener("pointercancel", up);
    };
    handle.addEventListener("pointermove", move);
    handle.addEventListener("pointerup", up);
    handle.addEventListener("pointercancel", up);
  };
  return [point, setPoint, onPointerDown];
};

// 读取元素相对舞台的盒子；锚点定位由浏览器在布局阶段算好，这里只读结果
const useBoxes = (stageRef, refs, deps) => {
  const [boxes, setBoxes] = useState(null);
  const measureRef = useRef(() => {});
  measureRef.current = () => {
    const stage = stageRef.current;
    if (!stage) return;
    // 以舞台的内边距盒为原点，与绝对定位的 left/top 同一坐标系
    const stageRect = stage.getBoundingClientRect();
    const originX = stageRect.left + stage.clientLeft;
    const originY = stageRect.top + stage.clientTop;
    const next = { stage: { left: 0, top: 0, width: stage.clientWidth, height: stage.clientHeight } };
    for (const [key, ref] of Object.entries(refs)) {
      const rect = ref.current?.getBoundingClientRect();
      if (rect) next[key] = { left: rect.left - originX, top: rect.top - originY, width: rect.width, height: rect.height };
    }
    setBoxes(next);
  };
  useLayoutEffect(() => {
    measureRef.current();
    // 子组件在同一帧内可能还会修正自身尺寸，下一帧再读一次
    const frame = requestAnimationFrame(() => measureRef.current());
    return () => cancelAnimationFrame(frame);
  }, deps);
  useEffect(() => {
    const observer = new ResizeObserver(() => measureRef.current());
    observer.observe(stageRef.current);
    return () => observer.disconnect();
  }, []);
  return boxes;
};

const px = value => `${Math.round(value)}px`;

// CSS 代码视图：{ text } 片段为当前正在调整的值
const CssView = ({ lines }) => (
  <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, index) => (
      <div key={index}>
        {line.map((part, partIndex) =>
          typeof part === "string" ? (
            <span key={partIndex}>{part}</span>
          ) : (
            <span key={partIndex} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.text}
            </span>
          )
        )}
      </div>
    ))}
  </pre>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-tau-sm text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 锚点定位按布局盒计算、不认 transform，所以居中用实测尺寸偏移而不是 translate
const AnchorHandle = ({ handleRef, point, onPointerDown, label = "锚点", style }) => {
  const [size, setSize] = useState({ width: 0, height: 0 });
  useLayoutEffect(() => {
    const handle = handleRef.current;
    setSize({ width: handle.offsetWidth, height: handle.offsetHeight });
  }, [label]);
  return (
    <button
      ref={handleRef}
      type="button"
      onPointerDown={onPointerDown}
      className="absolute flex cursor-grab touch-none select-none items-center gap-1 whitespace-nowrap rounded-tau-sm bg-accent px-2.5 py-1.5 text-tau-sm text-ink-inverse shadow-card active:cursor-grabbing"
      style={{
        left: `calc(${point.x * 100}% - ${size.width / 2}px)`,
        top: `calc(${point.y * 100}% - ${size.height / 2}px)`,
        anchorName: "--cb-anchor",
        ...style,
      }}
    >
      <icons.Move className="pointer-events-none size-3.5" />
      <span className="pointer-events-none">{label}</span>
    </button>
  );
};

const Floating = ({ floatRef, style, className = "", children }) => (
  <div
    ref={floatRef}
    className={`absolute rounded-tau-sm border border-line-1 bg-surface px-3 py-2 text-tau-sm text-ink-1 shadow-card ${className}`}
    style={{ positionAnchor: "--cb-anchor", ...style }}
  >
    {children}
  </div>
);

// 浮层落在锚点的哪一侧：完全在外为「上方/左侧」等，有重叠时按中心点偏向
const sideOf = (float, anchor) => {
  if (!float || !anchor) return "—";
  const axis = (start, size, anchorStart, anchorSize, [before, after, toBefore, toAfter]) => {
    if (start + size <= anchorStart + 1) return before;
    if (start >= anchorStart + anchorSize - 1) return after;
    const delta = start + size / 2 - (anchorStart + anchorSize / 2);
    return delta > 2 ? toAfter : delta < -2 ? toBefore : "居中";
  };
  const vertical = axis(float.top, float.height, anchor.top, anchor.height, ["上方", "下方", "偏上", "偏下"]);
  const horizontal = axis(float.left, float.width, anchor.left, anchor.width, ["左侧", "右侧", "偏左", "偏右"]);
  return vertical === "居中" && horizontal === "居中" ? "重叠" : `${vertical} · ${horizontal}`;
};

const ROWS = ["top", "center", "bottom", "span-top", "span-bottom", "span-all"];
const COLS = ["left", "center", "right", "span-left", "span-right", "span-all"];
const ROW_BANDS = { top: [0], center: [1], bottom: [2], "span-top": [0, 1], "span-bottom": [1, 2], "span-all": [0, 1, 2] };
const COL_BANDS = { left: [0], center: [1], right: [2], "span-left": [0, 1], "span-right": [1, 2], "span-all": [0, 1, 2] };
const LOGICAL = {
  top: "block-start", bottom: "block-end", left: "inline-start", right: "inline-end",
  "span-top": "span-block-start", "span-bottom": "span-block-end", "span-left": "span-inline-start", "span-right": "span-inline-end",
};
const CELLS = [
  ["top", "left"], ["top", "center"], ["top", "right"],
  ["center", "left"], ["center", "center"], ["center", "right"],
  ["bottom", "left"], ["bottom", "center"], ["bottom", "right"],
];

const STYLE = `
  @scope {
    .cb-stage {
      anchor-scope: all;
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
  }
`;

const areaValue = (row, col, logical) => {
  if (row === col && (row === "center" || row === "span-all")) return row;
  const name = value => (logical ? LOGICAL[value] ?? value : value);
  return `${name(row)} ${name(col)}`;
};

const Component = () => {
  const stageRef = useRef(null);
  const anchorRef = useRef(null);
  const floatRef = useRef(null);
  const [point, setPoint, onPointerDown] = useDraggable(stageRef, { x: 0.5, y: 0.5 });
  const [row, setRow] = useState("top");
  const [col, setCol] = useState("center");
  const [logical, setLogical] = useState(false);
  const area = areaValue(row, col, logical);
  const boxes = useBoxes(stageRef, { anchor: anchorRef, float: floatRef }, [point, area]);

  // 由锚点四条边切出的九宫格，用来画辅助线和高亮所选区域
  const grid = boxes?.anchor && {
    x: [0, boxes.anchor.left, boxes.anchor.left + boxes.anchor.width, boxes.stage.width],
    y: [0, boxes.anchor.top, boxes.anchor.top + boxes.anchor.height, boxes.stage.height],
  };
  const region = grid && (() => {
    const rows = ROW_BANDS[row];
    const cols = COL_BANDS[col];
    const top = grid.y[rows[0]];
    const left = grid.x[cols[0]];
    return { left, top, width: grid.x[cols[cols.length - 1] + 1] - left, height: grid.y[rows[rows.length - 1] + 1] - top };
  })();

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div ref={stageRef} className="cb-stage relative h-[280px] min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          {region && (
            <div
              className="pointer-events-none absolute rounded-tau-sm border border-dashed border-accent bg-accent-soft"
              style={{ left: region.left, top: region.top, width: region.width, height: region.height }}
            />
          )}
          {grid && (
            <svg className="pointer-events-none absolute inset-0 size-full overflow-visible">
              {[grid.x[1], grid.x[2]].map((x, index) => (
                <line key={`x${index}`} x1={x} x2={x} y1="0" y2="100%" className="stroke-line-1" strokeDasharray="4 4" />
              ))}
              {[grid.y[1], grid.y[2]].map((y, index) => (
                <line key={`y${index}`} x1="0" x2="100%" y1={y} y2={y} className="stroke-line-1" strokeDasharray="4 4" />
              ))}
            </svg>
          )}
          <AnchorHandle handleRef={anchorRef} point={point} onPointerDown={onPointerDown} />
          <Floating floatRef={floatRef} style={{ positionArea: area }}>
            浮层
          </Floating>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <div className="flex items-start gap-3">
            <div className="grid w-[96px] shrink-0 grid-cols-3 gap-1">
              {CELLS.map(([cellRow, cellCol]) => {
                const active = cellRow === row && cellCol === col;
                return (
                  <button
                    key={`${cellRow}-${cellCol}`}
                    type="button"
                    aria-label={areaValue(cellRow, cellCol, false)}
                    onClick={() => {
                      setRow(cellRow);
                      setCol(cellCol);
                    }}
                    className={`grid aspect-square cursor-pointer place-items-center rounded-tau-sm border ${
                      active ? "border-accent bg-accent-soft" : "border-line-1 hover:bg-hover"
                    }`}
                  >
                    {cellRow === "center" && cellCol === "center" && <span className="size-2 rounded-full bg-accent" />}
                  </button>
                );
              })}
            </div>
            <div className="flex min-w-0 flex-1 flex-col gap-2">
              <ui.Select size="sm" aria-label="行" options={ROWS.map(value => ({ value, label: value }))} value={row} onValueChange={setRow} />
              <ui.Select size="sm" aria-label="列" options={COLS.map(value => ({ value, label: value }))} value={col} onValueChange={setCol} />
              <ui.Switch checked={logical} onCheckedChange={setLogical} label="逻辑关键字" />
            </div>
          </div>
          <CssView
            lines={[
              [".tooltip {"],
              ["  position: absolute;"],
              ["  position-anchor: --anchor;"],
              ["  position-area: ", { text: area }, ";"],
              ["}"],
            ]}
          />
          <Readout
            rows={[
              ["可用区域", region ? `${px(region.width)} × ${px(region.height)}` : "—"],
              ["浮层位置", sideOf(boxes?.float, boxes?.anchor)],
            ]}
          />
        </div>
      </div>
      <p className="m-0 text-tau-meta text-ink-3">拖动锚点，浮层始终落在所选区域内；虚线是锚点四条边延伸出的九宫格。</p>
    </div>
  );
};

