            {guideX !== null && <line x1={guideX} x2={guideX} y1="0" y2="100%" className="stroke-accent" strokeDasharray="4 4" />}
            {guideY !== null && <line x1="0" x2="100%" y1={guideY} y2={guideY} className="stroke-accent" strokeDasharray="4 4" />}
