            <span className="absolute -left-1 -top-1 size-2 rounded-full bg-accent" />
            浮层的左上角
          </Floating>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <CssView
            lines={[
              [".tooltip {"],
              ["  position: absolute;"],
              ["  left: ", { text: left }, ";"],
              ["  top: ", { text: top }, ";"],
              ["}"],
            ]}
          />
          <Readout
            rows={[
              ["浮层 left", boxes?.float ? px(boxes.float.left) : "—"],
              ["浮层 top", boxes?.float ? px(boxes.float.top) : "—"],
              ["锚点", hasAnchor ? (anchor ? `${px(anchor.left)}, ${px(anchor.top)} · ${px(anchor.width)} × ${px(anchor.height)}` : "—") : "不存在，使用后备值"],
            ]}
          />
        </div>
      </div>
