      className="absolute flex cursor-grab touch-none select-none items-center gap-1 whitespace-nowrap rounded-tau-sm bg-accent px-2.5 py-1.5 text-tau-sm text-ink-inverse shadow-card active:cursor-grabbing"
      style={{
        left: `calc(${point.x * 100}% - ${size.width / 2}px)`,
        top: `calc(${point.y * 100}% - ${size.height / 2}px)`,
        anchorName: "--cb-anchor",
        ...style,
      }}
    >
      <icons.Move className="pointer-events-none size-3.5" />
      <span className="pointer-events-none">{label}</span>
    </button>
  );
};

const Floating = ({ floatRef, style, className = "", children }) => (
  <div
    ref={floatRef}
    className={`absolute rounded-tau-sm border border-line-1 bg-surface px-3 py-2 text-tau-sm text-ink-1 shadow-card ${className}`}
    style={{ positionAnchor: "--cb-anchor", ...style }}
  >
    {children}
  </div>
);

// 浮层落在锚点的哪一侧：完全在外为「上方/左侧」等，有重叠时按中心点偏向
const sideOf = (float, anchor) => {
  if (!float || !anchor) return "—";
  const axis = (start, size, anchorStart, anchorSize, [before, after, toBefore, toAfter]) => {
    if (start + size <= anchorStart + 1) return before;
    if (start >= anchorStart + anchorSize - 1) return after;
    const delta = start + size / 2 - (anchorStart + anchorSize / 2);
    return delta > 2 ? toAfter : delta < -2 ? toBefore : "居中";
  };
  const vertical = axis(float.top, float.height, anchor.top, anchor.height, ["上方", "下方", "偏上", "偏下"]);
  const horizontal = axis(float.left, float.width, anchor.left, anchor.width, ["左侧", "右侧", "偏左", "偏右"]);
  return vertical === "居中" && horizontal === "居中" ? "重叠" : `${vertical} · ${horizontal}`;
};

const ORDERS = ["normal", "most-height"];
const START = { x: 0.5, y: 0.38 };

const STYLE = `
  @scope {
    .cb-stage {
      anchor-scope: all;
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
  }
`;

const Space = ({ label, value, active }) => (
  <div className={`flex flex-1 flex-col gap-1 rounded-tau-sm border px-3 py-2 ${active ? "border-accent bg-accent-soft" : "border-line-1"}`}>
    <span className={`text-tau-sm ${active ? "text-accent-text" : "text-ink-3"}`}>{label}</span>
    <span className="font-tau-mono text-tau-body text-ink-1">{value === null ? "—" : px(value)}</span>
  </div>
);

const Component = () => {
  const stageRef = useRef(null);
  const anchorRef = useRef(null);
  const floatRef = useRef(null);
  const [point, setPoint, onPointerDown] = useDraggable(stageRef, START);
  const [order, setOrder] = useState("most-height");
  const boxes = useBoxes(stageRef, { anchor: anchorRef, float: floatRef }, [point, order]);
  const anchor = boxes?.anchor;
  const above = anchor ? anchor.top : 0;
  const below = anchor ? boxes.stage.height - anchor.top - anchor.height : 0;
  const side = sideOf(boxes?.float, anchor);
  const placed = side.startsWith("上方") ? "top" : side.startsWith("下方") ? "bottom" : null;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div ref={stageRef} className="cb-stage relative h-[300px] min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          {anchor && (
            <>
              <div className="pointer-events-none absolute inset-x-0 top-0 border-b border-dashed border-line-1" style={{ height: above }} />
              <div className="pointer-events-none absolute inset-x-0 bottom-0 border-t border-dashed border-line-1" style={{ height: below }} />
            </>
          )}
          <AnchorHandle handleRef={anchorRef} point={point} onPointerDown={onPointerDown} />
          <Floating
            floatRef={floatRef}
            className="flex w-[168px] flex-col gap-1"
            style={{ positionArea: "top", marginBlock: 8, positionTryFallbacks: "bottom", positionTryOrder: order }}
          >
            <span>提示浮层</span>
            <span className="h-1.5 w-full rounded-full bg-press" />
            <span className="h-1.5 w-3/4 rounded-full bg-press" />
            <span className="h-1.5 w-1/2 rounded-full bg-press" />
          </Floating>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <CssView
            lines={[
              [".tooltip {"],
              ["  position-area: top;"],
              ["  position-try-fallbacks: bottom;"],
              ["  position-try-order: ", { text: order }, ";"],
              ["}"],
            ]}
          />
          <div className="flex gap-2">
            <Space label="上方可用高度" value={anchor ? above : null} active={placed === "top"} />
            <Space label="下方可用高度" value={anchor ? below : null} active={placed === "bottom"} />
          </div>
          <Readout rows={[["实际位置", side]]} />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.RadioGroup label="position-try-order" value={order} onValueChange={setOrder} orientation="horizontal">
          {ORDERS.map(value => (
            <ui.Radio key={value} value={value} label={value} />
          ))}
        </ui.RadioGroup>
        <span className="text-tau-meta text-ink-3">上下拖动锚点：normal 能放下就留在上方，most-height 总选更高的一侧</span>
      </div>
    </div>
  );
};

