const { useEffect, useLayoutEffect, useRef, useState } = React;

// ---- Anchor Positioning 实验台（本文各块共用）----


// 读取元素相对舞台的盒子；锚点定位由浏览器在布局阶段算好，这里只读结果
const useBoxes = (stageRef, refs, deps) => {
  const [boxes, setBoxes] = useState(null);
  const measureRef = useRef(() => {});
  measureRef.current = () => {
    const stage = stageRef.current;
    if (!stage) return;
    // 以舞台的内边距盒为原点，与绝对定位的 left/top 同一坐标系
    const stageRect = stage.getBoundingClientRect();
    const originX = stageRect.left + stage.clientLeft;
    const originY = stageRect.top + stage.clientTop;
    const next = { stage: { left: 0, top: 0, width: stage.clientWidth, height: stage.clientHeight } };
    for (const [key, ref] of Object.entries(refs)) {
      const rect = ref.current?.getBoundingClientRect();
      if (rect) next[key] = { left: rect.left - originX, top: rect.top - originY, width: rect.width, height: rect.height };
    }
    setBoxes(next);
  };
  useLayoutEffect(() => {
    measureRef.current();
    // 子组件在同一帧内可能还会修正自身尺寸，下一帧再读一次
    const frame = requestAnimationFrame(() => measureRef.current());
    return () => cancelAnimationFrame(frame);
  }, deps);
  useEffect(() => {
    const observer = new ResizeObserver(() => measureRef.current());
    observer.observe(stageRef.current);
    return () => observer.disconnect();
  }, []);
  return boxes;
};


// CSS 代码视图：{ text } 片段为当前正在调整的值
const CssView = ({ lines }) => (
  <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, index) => (
      <div key={index}>
        {line.map((part, partIndex) =>
          typeof part === "string" ? (
            <span key={partIndex}>{part}</span>
          ) : (
            <span key={partIndex} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.text}
            </span>
          )
        )}
      </div>
    ))}
  </pre>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-tau-sm text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 锚点定位按布局盒计算、不认 transform，所以居中用实测尺寸偏移而不是 translate

const MODES = ["always", "anchors-visible", "no-overflow"];
const ROWS = Array.from({ length: 14 }, (_, index) => index + 1);
const ANCHOR_ROW = 5;

const STYLE = `
  @scope {
    .cb-stage {
      anchor-scope: all;
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
  }
`;

const Component = () => {
  const stageRef = useRef(null);
  const scrollerRef = useRef(null);
  const anchorRef = useRef(null);
  const floatRef = useRef(null);
  const [mode, setMode] = useState("anchors-visible");
  const [scrollTop, setScrollTop] = useState(0);
  const boxes = useBoxes(stageRef, { float: floatRef, anchor: anchorRef, scroller: scrollerRef }, [mode, scrollTop]);
  const { anchor, scroller } = boxes ?? {};
  // 锚点行与滚动容器可视区还有交集即算可见
  const anchorVisible = !anchor || !scroller || (anchor.top + anchor.height > scroller.top + 1 && anchor.top < scroller.top + scroller.height - 1);

  const float = boxes?.float;
  const overflow = float && (float.top < 0 || float.top + float.height > boxes.stage.height);
  const shown = mode === "always" || (mode === "anchors-visible" ? anchorVisible : !overflow);

  const scrollToAnchor = () => {
    const scroller = scrollerRef.current;
    const row = anchorRef.current;
    scroller.scrollTo({ top: row.offsetTop - scroller.clientHeight / 2 + row.offsetHeight / 2, behavior: "smooth" });
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div ref={stageRef} className="cb-stage relative flex h-[280px] min-w-0 items-center overflow-hidden rounded-tau-md border border-line-1 px-4">
          <div
            ref={scrollerRef}
            onScroll={event => setScrollTop(event.currentTarget.scrollTop)}
            className="h-[150px] w-[52%] min-w-[120px] overflow-y-auto rounded-tau-sm border border-line-1 bg-surface p-1"
          >
            {ROWS.map(row => (
              <div
                key={row}
                ref={row === ANCHOR_ROW ? anchorRef : undefined}
                className={`flex items-center gap-2 rounded-tau-sm px-2 py-1.5 text-tau-sm ${row === ANCHOR_ROW ? "bg-accent-soft text-accent-text" : "text-ink-2"}`}
                style={row === ANCHOR_ROW ? { anchorName: "--cb-row" } : undefined}
              >
                <span className="font-tau-mono text-tau-tiny text-ink-3">{String(row).padStart(2, "0")}</span>
                {row === ANCHOR_ROW ? "锚点行" : "列表项"}
              </div>
            ))}
          </div>
          <div
            ref={floatRef}
            className="absolute w-max max-w-[40%] rounded-tau-sm border border-line-1 bg-surface px-3 py-2 text-tau-sm text-ink-1 shadow-card"
            style={{ positionAnchor: "--cb-row", positionArea: "right", marginLeft: 8, positionVisibility: mode }}
          >
            跟随锚点行
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <CssView
            lines={[
              [".tooltip {"],
              ["  position-anchor: --row;"],
              ["  position-area: right;"],
              ["  position-visibility: ", { text: mode }, ";"],
              ["}"],
            ]}
          />
          <Readout
            rows={[
              ["锚点", anchorVisible ? "在滚动容器内可见" : "已滚出可视区"],
              ["浮层", overflow ? "超出舞台" : "在舞台内"],
              ["按规则", shown ? "显示" : "隐藏"],
            ]}
          />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.RadioGroup label="position-visibility" value={mode} onValueChange={setMode} orientation="horizontal">
          {MODES.map(value => (
            <ui.Radio key={value} value={value} label={value} />
          ))}
        </ui.RadioGroup>
        <ui.Button variant="ghost" size="sm" icon={icons.Crosshair} onClick={scrollToAnchor}>
          滚回锚点
        </ui.Button>
      </div>
      <p className="m-0 text-tau-meta text-ink-3">滚动左侧列表，把锚点行滚出可视区，对比三种取值下浮层是否隐藏。</p>
    </div>
  );
};
